#include "../common.h"
int main(void){char bits[100];int key=0x1FD,iv=0xAA,prev=iv,cbytes[100],n=0;printf("Enter plaintext bytes as hex (example: 010203): ");scanf("%99s",bits);printf("Ciphertext: ");for(int i=0;bits[2*i]&&bits[2*i+1];i++){unsigned x=0;sscanf(bits+2*i,"%2x",&x);int c=sdes8((int)x^prev,key,0);cbytes[n++]=c;printf("%02X",c);prev=c;}puts("");prev=iv;printf("Decrypted: ");for(int i=0;i<n;i++){int p=sdes8(cbytes[i],key,1)^prev;printf("%02X",p);prev=cbytes[i];}puts("");puts("Educational S-DES CBC demonstration using the worksheet's 10-bit key and IV.");return 0;}